recipes.code:
{
  "inputs": [
    {
      "id": "situation-atlas-api-key",
      "type": "promptString",
      "description": "Situation Atlas API key (sa_...) — create one at https://situationatlas.com after signup",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@situationatlas/mcp@0.1.0"
      ],
      "env": {
        "SITUATION_ATLAS_API_KEY": "${input:situation-atlas-api-key}"
      }
    }
  }
}
